"""Registered perspective of child candidate base+rear+down runtime stack."""
from pathlib import Path
import argparse,json,math
import numpy as np
from stack_math import rays,sample,sha,load,save
p=argparse.ArgumentParser();p.add_argument('--base',type=Path,required=True);p.add_argument('--rear',type=Path,required=True);p.add_argument('--down',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--yaw-radians',type=float,default=math.pi);p.add_argument('--pitch-radians',type=float,default=-.7);p.add_argument('--fov',type=float,default=90);p.add_argument('--size',type=int,default=1400);a=p.parse_args();paths={'base':a.base,'rear':a.rear,'down':a.down};images={k:load(v)[...,:3] for k,v in paths.items()};config={'fovDegrees':110,'frontMask':[0,0,1,1]};w=rays(a.size,a.yaw_radians,a.pitch_radians,a.fov);values,_=sample(images,config,w,['rear','down']);result=np.rint(np.clip(values,0,255)).astype(np.uint8);save(a.output,result)
record={'schemaVersion':1,'operation':'candidate full base+rear+down perspective extraction for registered detail','inputs':{k:{'path':str(v),'sha256':sha(v)} for k,v in paths.items()},'output':{'path':str(a.output),'sha256':sha(a.output),'size':[a.size,a.size]},'camera':{'yawRadians':a.yaw_radians,'pitchRadians':a.pitch_radians,'horizontalFovDegrees':a.fov,'verticalFovDegrees':a.fov},'repairs':{'fovDegrees':110,'edgeFull':.70,'edgeZero':.96,'blend':'Normalized runtime blend, base=1-max(repair weights), no directional down mask in child candidate'},'scriptSha256':sha(__file__),'stackMathSha256':sha(Path(__file__).with_name('stack_math.py')),'noArtisticEditing':True};a.output.with_suffix('.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record['output']))
